<?php
/**
 * Site content API — serves the content seeded in MySQL.
 * Requires config.php in the document root (generated by install.sh).
 *
 *   GET /api/site-content.php              → all sections as JSON
 *   GET /api/site-content.php?section=hero_name → one section
 */
require_once __DIR__ . '/../config.php';

header('Content-Type: application/json; charset=utf-8');
header('Cache-Control: no-cache');

try {
    $pdo = new PDO(
        'mysql:host=' . DB_HOST . ';dbname=' . DB_NAME . ';charset=utf8mb4',
        DB_USER,
        DB_PASS,
        [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION]
    );

    if (isset($_GET['section'])) {
        $stmt = $pdo->prepare('SELECT section, content FROM site_content WHERE section = :s LIMIT 1');
        $stmt->execute([':s' => $_GET['section']]);
        $row = $stmt->fetch(PDO::FETCH_ASSOC);
        echo $row
            ? json_encode($row, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE)
            : json_encode(['error' => 'section not found']);
    } else {
        $rows = $pdo->query('SELECT section, content FROM site_content ORDER BY id')
                    ->fetchAll(PDO::FETCH_ASSOC);
        echo json_encode($rows, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
    }
} catch (PDOException $e) {
    http_response_code(500);
    echo json_encode(['error' => 'database unavailable']);
}
